//! 🤝️ Qualified editor and read-only facets borrow the same actual member custody and registered producer pair.
use super::custody::{ChildReadSourceCustody,ChildEditorSourceCustody};
use crate::child_view::child_editor::{registration::ChildEditorRegistration,source::ChildEditorStamp};
use semio_framework_io_ports::{ChildAdmissionAddress,ChildAdmissionProviderV1,ChildAdmissionRead,ChildAdmissionQualificationV1,EmbeddedChildAdmitterV1,EmbeddedChildVectorSourceV1};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retirement::RetireOwned,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,retained_clone_grant_admits}};
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
pub struct QualifiedChildAdmissionProvider<'a,S:RetireOwned+Sync,Q:RetireOwned+Sync+Copy+Eq+ChildAdmissionQualificationV1>{custody:&'a ChildReadSourceCustody<S,Q>,capability:usize,admitter:&'static dyn EmbeddedChildAdmitterV1,vector:&'static dyn EmbeddedChildVectorSourceV1,address:ChildAdmissionAddress}
pub type ChildEditorAdmissionProvider<'a,S:RetireOwned+Sync>=QualifiedChildAdmissionProvider<'a,S,ChildEditorStamp>;
impl<'a,S:RetireOwned+Sync,Q:RetireOwned+Sync+Copy+Eq+ChildAdmissionQualificationV1> QualifiedChildAdmissionProvider<'a,S,Q>{
 const HEADER:usize=std::mem::size_of::<Self>()*2;
 pub fn demand()->RetirementDemand{let d=ChildAdmissionAddress::demand();RetirementDemand{copy_bytes:d.copy_bytes+Self::HEADER,depth:d.depth+1,..d}}
 pub(crate) fn admit_registered(custody:&'a ChildReadSourceCustody<S,Q>,capability:usize,admitter:&'static dyn EmbeddedChildAdmitterV1,vector:&'static dyn EmbeddedChildVectorSourceV1,ordinal:usize,g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::demand();if !retained_clone_grant_admits(g,d){return Err(refusal("Qualified child admission provider birth is unfunded"))}let own=RetainedCloneProgress{copied_items:1,copied_bytes:Self::HEADER,..Default::default()};if !custody.ready(){return Err(refusal("Qualified child admission custody is not ready").with_retained_progress(own))}let stamp=custody.stamp().ok_or_else(||refusal("Qualified child admission stamp is absent").with_retained_progress(own))?;if stamp.child_admission_stamp().capability_identity!=capability{return Err(refusal("Qualified child admission registration changed").with_retained_progress(own))}let child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-Self::HEADER,maximum_depth:g.maximum_depth-1,..g};let(address,mut p)=ChildAdmissionAddress::admit(ordinal,stamp,child).map_err(|error|{let mut p=error.retained_progress();p.copied_items=p.copied_items.max(1);p.copied_bytes=p.copied_bytes.saturating_add(Self::HEADER);error.with_retained_progress(p)})?;p.copied_bytes+=Self::HEADER;Ok((Self{custody,capability,admitter,vector,address},p))}
 pub fn address(&self)->ChildAdmissionAddress{self.address}
}
impl<'a,S:RetireOwned+Sync> QualifiedChildAdmissionProvider<'a,S,ChildEditorStamp>{pub fn admit(custody:&'a ChildEditorSourceCustody<S>,registration:&'static ChildEditorRegistration<S>,ordinal:usize,g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{Self::admit_registered(custody,&registration.identity as*const _ as usize,registration.admission,registration.vector,ordinal,g)}}
impl<S:RetireOwned+Sync,Q:RetireOwned+Sync+Copy+Eq+ChildAdmissionQualificationV1> ChildAdmissionProviderV1 for QualifiedChildAdmissionProvider<'_,S,Q>{
 fn read(&self,address:ChildAdmissionAddress)->Result<ChildAdmissionRead<'_>,ValueError>{let stamp=self.custody.stamp().ok_or_else(||refusal("Qualified child admission stamp is absent"))?;if !self.custody.ready()||address.ordinal()!=self.address.ordinal()||!address.matches(stamp)||stamp.child_admission_stamp().capability_identity!=self.capability{return Err(refusal("Qualified child admission route or original custody changed"))}Ok(ChildAdmissionRead{source:self.custody.opaque_source()?,admitter:self.admitter,vector:self.vector})}
}
#[cfg(test)]#[path="🧪️tests.rs"]mod tests;
